/**
 * This class implements a plaintext-based editable file view, which can be
 * loaded and saved given an editor.
 *
 * Note that by default, this view only saves when it's closing. To implement
 * auto-save, your editor should call `this.requestSave()` when the content is
 * changed.
 *
 * @since 0.10.12
 * @public
 */
export abstract class TextFileView extends EditableFileView {
  /**
   * In memory data
   *
   * @since 0.10.12
   * @public
   */
  data: string;
  /**
   * Debounced save in 2 seconds from now
   *
   * @since 0.10.12
   * @public
   */
  requestSave: () => void;

  /** @public */
  constructor(leaf: WorkspaceLeaf);

  /**
   * @since 0.10.12
   * @public
   */
  onUnloadFile(file: TFile): Promise<void>;
  /**
   * @since 0.10.12
   * @public
   */
  onLoadFile(file: TFile): Promise<void>;

  /**
   * @since 0.10.12
   * @public
   */
  save(clear?: boolean): Promise<void>;

  /**
   * Gets the data from the editor. This will be called to save the editor
   * contents to the file.
   *
   * @since 0.10.12
   * @public
   */
  abstract getViewData(): string;
  /**
   * Set the data to the editor. This is used to load the file contents.
   *
   * If clear is set, then it means we're opening a completely different file.
   * In that case, you should call clear(), or implement a slightly more
   * efficient clearing mechanism given the new data to be set.
   *
   * @since 0.10.12
   * @public
   */
  abstract setViewData(data: string, clear: boolean): void;
  /**
   * Clear the editor. This is usually called when we're about to open a
   * completely different file, so it's best to clear any editor states like
   * undo-redo history, and any caches/indexes associated with the previous file
   * contents.
   *
   * @since 0.10.12
   * @public
   */
  abstract clear(): void;
}

